import { THEME, type ThemeToken } from './palette';

/** `seaDeepest` → `sea-deepest`. */
export function kebab(name: string): string {
  return name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
}

/** CSS custom properties for every theme token, e.g. `--c-sea-deepest`. */
export function renderPaletteCss(): string {
  const lines = (Object.keys(THEME) as ThemeToken[]).map(
    (name) => `  --c-${kebab(name)}: ${THEME[name]};`,
  );
  return [
    '/* Generated by `npm run art` from tools/genart/palette.ts. Do not edit. */',
    ':root {',
    ...lines,
    '}',
    '',
  ].join('\n');
}
